import { ListPage } from "@/components/openlmis/list-page/list-page"

// A Next.js App Router route; in any other React app, render ListPage from your own route.
export default function Page() {
  return <ListPage />
}

"use client"

import {
  type ColumnVisibilityState,
  functionalUpdate,
  useTable,
} from "@tanstack/react-table"
import { PlusIcon, SearchXIcon, UsersIcon } from "lucide-react"
import { useCallback, useMemo, useState } from "react"

import { Button } from "@/components/ui/button"
import { PageBreadcrumbs } from "@/components/openlmis/page-breadcrumbs"
import {
  DataTable,
  DataTableEmpty,
  DataTablePagination,
  dataTableFeatures,
} from "@/components/blocks/openlmis/data-table/data-table"
import {
  useColumnVisibility,
  useContainerSize,
} from "@/components/blocks/openlmis/data-table/responsive-columns"
import {
  ListToolbar,
  ListToolbarEnd,
  ListToolbarFilter,
  ListToolbarSearch,
} from "@/components/blocks/openlmis/list-toolbar"
import {
  Workspace,
  WorkspaceContent,
  WorkspaceDescription,
  WorkspaceHeader,
  WorkspaceHeading,
  WorkspaceIcon,
  WorkspaceTitle,
} from "@/components/blocks/openlmis/workspace"
import { ColumnViewOptions } from "@/components/openlmis/column-view-options"
import { SearchInput } from "@/components/openlmis/search-input/search-input"
import { SelectFilter } from "@/components/openlmis/select-filter"
import {
  type PasswordDialogTarget,
  ResetPasswordDialog,
} from "@/components/blocks/openlmis/reset-password-dialog/reset-password-dialog"
import {
  UserFormDialog,
  type UserFormDialogTarget,
} from "@/components/blocks/openlmis/user-form-dialog/user-form-dialog"

import { MOCK_FACILITIES, type User, type UsersQuery } from "@/components/openlmis/list-page/mock-users"
import { createUserColumns, HIDEABLE_COLUMNS } from "@/components/openlmis/list-page/user-columns"
import { useUserList } from "@/components/openlmis/list-page/use-user-list"

const getRowId = (user: User) => user.id

// One dialog at a time: adding a user hands over to Set Password rather than stacking a second dialog.
type OpenDialog =
  | { kind: "user"; target: UserFormDialogTarget }
  | { kind: "password"; target: PasswordDialogTarget }

/** The whole users list screen; mount it from any route, e.g. the `page.tsx` this template ships. */
export function ListPage() {
  const list = useUserList()
  const { query, update, page } = list
  const [dialog, setDialog] = useState<OpenDialog>()
  const [saveError, setSaveError] = useState<string>()
  const closeDialog = () => {
    setDialog(undefined)
    setSaveError(undefined)
  }
  const userTarget = dialog?.kind === "user" ? dialog.target : undefined
  const passwordTarget = dialog?.kind === "password" ? dialog.target : undefined
  const findUser = (userId: string | undefined) =>
    list.users.find((user) => user.id === userId)
  // Stable, so the columns built from them keep their identity between renders.
  const onEdit = useCallback(
    (userId: string) => setDialog({ kind: "user", target: userId }),
    []
  )
  const onResetPassword = useCallback(
    (userId: string) =>
      setDialog({ kind: "password", target: { userId, created: false } }),
    []
  )
  const columns = useMemo(
    () => createUserColumns({ onEdit, onResetPassword }),
    [onEdit, onResetPassword]
  )
  const [measureContent, contentSize] = useContainerSize<HTMLDivElement>()
  // Kept for the visit only; store it (e.g. in localStorage) to remember it across visits.
  const columnChoices = useState<ColumnVisibilityState>({})
  const columnView = useColumnVisibility(
    HIDEABLE_COLUMNS,
    columnChoices,
    contentSize
  )

  const pagination = { pageIndex: query.pageIndex, pageSize: query.pageSize }
  // Memoized: the table compares controlled state by reference and would reset it every render.
  const sorting = useMemo(
    () => [{ id: query.sortBy, desc: query.sortDesc }],
    [query.sortBy, query.sortDesc]
  )

  const table = useTable({
    features: dataTableFeatures,
    columns,
    data: page.rows,
    getRowId,
    rowCount: page.total,
    manualPagination: true,
    manualSorting: true,
    enableSortingRemoval: false,
    state: { pagination, sorting, columnVisibility: columnView.visibility },
    onPaginationChange: (updater) =>
      update(functionalUpdate(updater, pagination)),
    onSortingChange: (updater) => {
      const [next] = functionalUpdate(updater, sorting)
      if (next)
        update({ sortBy: next.id as UsersQuery["sortBy"], sortDesc: next.desc })
    },
  })

  return (
    <Workspace>
      <PageBreadcrumbs
        items={[
          { label: "Home", href: "#" },
          { label: "Administration" },
          { label: "Users" },
        ]}
      />
      <WorkspaceHeader>
        <WorkspaceHeading>
          <WorkspaceIcon>
            <UsersIcon />
          </WorkspaceIcon>
          <WorkspaceTitle>Users</WorkspaceTitle>
          <WorkspaceDescription>
            Accounts that can sign in to OpenLMIS.
          </WorkspaceDescription>
        </WorkspaceHeading>
      </WorkspaceHeader>
      <WorkspaceContent>
        {/* Measured, because the room for columns depends on a sidebar as well as the window. */}
        <div className="flex flex-col gap-4" ref={measureContent}>
          <ListToolbar>
            <ListToolbarSearch>
              <SearchInput
                label="Search by username, name or email"
                onValueChange={(search) => update({ search })}
                value={query.search}
              />
            </ListToolbarSearch>
            <ListToolbarFilter>
              <SelectFilter
                label="Status"
                onValueChange={(status) =>
                  update({ status: status as UsersQuery["status"] })
                }
                options={[
                  { value: "active", label: "Active" },
                  { value: "inactive", label: "Inactive" },
                ]}
                value={query.status}
              />
            </ListToolbarFilter>
            <ListToolbarEnd>
              <ColumnViewOptions
                columns={HIDEABLE_COLUMNS}
                onReset={columnView.onReset}
                onVisibilityChange={columnView.onVisibilityChange}
                visibility={columnView.visibility}
              />
              <Button
                onClick={() => setDialog({ kind: "user", target: "new" })}
              >
                <PlusIcon data-icon="inline-start" />
                Add User
              </Button>
            </ListToolbarEnd>
          </ListToolbar>

          <DataTable
            empty={
              list.isFiltered ? (
                <DataTableEmpty
                  action={
                    <Button onClick={list.clearFilters} variant="destructive">
                      Clear Filters
                    </Button>
                  }
                  description="Try a different search or clear the filters."
                  icon={<SearchXIcon />}
                  title="No Matching Users"
                />
              ) : (
                <DataTableEmpty
                  description="Users added to OpenLMIS appear here."
                  icon={<UsersIcon />}
                  title="No Users Yet"
                />
              )
            }
            footer={page.total > 0 && <DataTablePagination table={table} />}
            table={table}
          />
        </div>
      </WorkspaceContent>

      <UserFormDialog
        error={saveError}
        facilities={MOCK_FACILITIES}
        onClose={closeDialog}
        onSubmit={(values, existing) => {
          const result = list.saveUser(values, existing)
          if ("error" in result) return setSaveError(result.error)
          setSaveError(undefined)
          // A new user has no password yet, so setting one comes next.
          setDialog(
            existing
              ? undefined
              : {
                  kind: "password",
                  target: { userId: result.id, created: true },
                }
          )
        }}
        target={userTarget}
        user={userTarget === "new" ? undefined : findUser(userTarget)}
      />
      <ResetPasswordDialog
        onClose={closeDialog}
        // Wire this to your own call that emails a reset link or sets the password.
        onSubmit={closeDialog}
        target={passwordTarget}
        user={findUser(passwordTarget?.userId)}
      />
    </Workspace>
  )
}

// Mock users and the rules the list applies to them, so the page runs with no backend.

import type {
  Facility,
  UserDetails,
  UserFormValues,
} from "@/components/blocks/openlmis/user-form-dialog/user-form"

export type User = {
  id: string
  username: string
  firstName: string
  lastName: string
  email: string | null
  active: boolean
}

export type UsersQuery = {
  pageIndex: number
  pageSize: number
  sortBy: "username" | "lastName" | "active"
  sortDesc: boolean
  /** Matches username, first or last name, or email. */
  search: string
  status: "" | "active" | "inactive"
}

export type UsersPage = {
  rows: User[]
  total: number
}

const FIRST_NAMES = [
  "Adora",
  "Alan",
  "Chimango",
  "Grace",
  "Ibrahim",
  "Lindiwe",
  "Mateus",
  "Nia",
  "Omar",
  "Priya",
  "Tendai",
  "Zara",
]
const LAST_NAMES = [
  "Adamovich",
  "Banda",
  "Costa",
  "Diallo",
  "Ehrenfreund",
  "Hopper",
  "Kamau",
  "Mwale",
  "Okafor",
  "Silva",
  "Tebulo",
  "Zulu",
]

export const MOCK_FACILITIES: Facility[] = [
  { id: "facility-1", code: "HC01", name: "Balaka District Hospital" },
  { id: "facility-2", code: "HC02", name: "Comfort Health Clinic" },
  { id: "facility-3", code: "HC03", name: "Kankao Health Facility" },
  { id: "facility-4", code: "HC04", name: "Nandumbo Health Center" },
  { id: "facility-5", code: "W001", name: "Ntcheu District Warehouse" },
]

export const MOCK_USERS: UserDetails[] = Array.from(
  { length: 57 },
  (_, index) => {
    const firstName = FIRST_NAMES[index % FIRST_NAMES.length] as string
    // Offset each round of first names, so no two users share a full name.
    const lastName = LAST_NAMES[
      (index + Math.floor(index / FIRST_NAMES.length)) % LAST_NAMES.length
    ] as string
    const username = `${firstName[0]}${lastName}${index + 1}`.toLowerCase()
    const email = index % 3 === 0 ? null : `${username}@example.org`
    // Only an address can be verified, and notifications need a verified one.
    const verified = email !== null && index % 2 === 0
    return {
      id: `user-${index + 1}`,
      username,
      firstName,
      lastName,
      email,
      emailVerified: verified,
      jobTitle: null,
      phoneNumber: null,
      active: index % 4 !== 0,
      homeFacilityId:
        MOCK_FACILITIES[index % MOCK_FACILITIES.length]?.id ?? null,
      allowNotify: verified,
      homeFacilityRoleCount: index % 3,
    }
  }
)

const toRow = ({ id, username, firstName, lastName, email, active }: User) => ({
  id,
  username,
  firstName,
  lastName,
  email,
  active,
})

/** One page of `users` for the list's search, filter, sort and paging. */
export function queryUsers(
  users: readonly UserDetails[],
  query: UsersQuery
): UsersPage {
  const term = query.search.trim().toLowerCase()
  const matches = users.filter((user) => {
    const text = `${user.username} ${user.firstName} ${user.lastName} ${user.email ?? ""}`
    const status =
      query.status === "" || user.active === (query.status === "active")
    return status && text.toLowerCase().includes(term)
  })

  // oxlint-disable-next-line unicorn/no-array-sort -- sorts a copy; toSorted needs the ES2023 lib
  const sorted = [...matches].sort((a, b) => {
    const order = String(a[query.sortBy]).localeCompare(String(b[query.sortBy]))
    return query.sortDesc ? -order : order
  })

  const start = query.pageIndex * query.pageSize
  return {
    rows: sorted.slice(start, start + query.pageSize).map(toRow),
    total: matches.length,
  }
}

/** The user the form describes, created or updated from `existing`. */
export function toSavedUser(
  values: UserFormValues,
  id: string,
  existing?: UserDetails
): UserDetails {
  return {
    id,
    username: values.username,
    firstName: values.firstName,
    lastName: values.lastName,
    email: values.email || null,
    // A changed address has to be verified again.
    emailVerified:
      existing !== undefined &&
      existing.emailVerified &&
      existing.email === (values.email || null),
    jobTitle: values.jobTitle || null,
    phoneNumber: values.phoneNumber || null,
    active: values.active,
    homeFacilityId: values.homeFacilityId,
    allowNotify: values.allowNotify,
    homeFacilityRoleCount: values.removeHomeFacilityRoles
      ? 0
      : (existing?.homeFacilityRoleCount ?? 0),
  }
}

"use client"

import { useMemo, useState } from "react"

import type {
  UserDetails,
  UserFormValues,
} from "@/components/blocks/openlmis/user-form-dialog/user-form"

import {
  MOCK_USERS,
  queryUsers,
  toSavedUser,
  type UsersQuery,
} from "@/components/openlmis/list-page/mock-users"

const INITIAL_QUERY: UsersQuery = {
  pageIndex: 0,
  pageSize: 10,
  sortBy: "username",
  sortDesc: false,
  search: "",
  status: "",
}

/** The list's users and state in plain React; swap `users` for your own data and `saveUser` for your save. */
export function useUserList() {
  const [users, setUsers] = useState(MOCK_USERS)
  const [query, setQuery] = useState(INITIAL_QUERY)
  const page = useMemo(() => queryUsers(users, query), [users, query])

  /** A filter or sort starts again from the first page; paging keeps the rest. */
  const update = (patch: Partial<UsersQuery>) =>
    setQuery((previous) => ({
      ...previous,
      ...patch,
      pageIndex: "pageIndex" in patch ? (patch.pageIndex ?? 0) : 0,
    }))

  /** Creates the user, or updates `existing`; returns its id, or why it could not be saved. */
  const saveUser = (
    values: UserFormValues,
    existing?: UserDetails
  ): { id: string } | { error: string } => {
    const taken = users.some(
      (user) => user.username === values.username && user.id !== existing?.id
    )
    if (taken) return { error: `Username ${values.username} is already taken.` }

    const id = existing?.id ?? `user-${users.length + 1}`
    const saved = toSavedUser(values, id, existing)
    setUsers((current) =>
      existing
        ? current.map((user) => (user.id === id ? saved : user))
        : [...current, saved]
    )
    return { id }
  }

  return {
    query,
    update,
    page,
    users,
    saveUser,
    /** Whether the rows come from a search or filter, which picks the empty state. */
    isFiltered: Boolean(query.search || query.status),
    clearFilters: () => update({ search: "", status: "" }),
  }
}

"use client"

import { createColumnHelper } from "@tanstack/react-table"
import {
  EllipsisIcon,
  KeyRoundIcon,
  PencilIcon,
  ShieldIcon,
} from "lucide-react"

import { Button } from "@/components/ui/button"
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu"
import {
  DataTableColumnHeader,
  type DataTableFeatures,
} from "@/components/blocks/openlmis/data-table/data-table"
import type { ResponsiveColumn } from "@/components/blocks/openlmis/data-table/responsive-columns"
import { StatusBadge } from "@/components/openlmis/status-badge"

import type { User } from "@/components/openlmis/list-page/mock-users"

/** The columns the View menu lists, in order; `hideBelow` drops them while the table is narrow. */
export const HIDEABLE_COLUMNS: (ResponsiveColumn & { label: string })[] = [
  { id: "lastName", label: "Name", hideBelow: "xl" },
  { id: "email", label: "Email", hideBelow: "4xl" },
  { id: "active", label: "Status" },
]

const columnHelper = createColumnHelper<DataTableFeatures, User>()

/** What the row menu does; Roles is left for you to wire to a screen of your own. */
export type UserRowActions = {
  onEdit: (userId: string) => void
  onResetPassword: (userId: string) => void
}

export const createUserColumns = (actions: UserRowActions) =>
  columnHelper.columns([
    // Shows the full name but sorts by last name, the usual order for a list of people.
    columnHelper.accessor("lastName", {
      header: ({ column }) => (
        <DataTableColumnHeader column={column} title="Name" />
      ),
      cell: ({ row }) => `${row.original.firstName} ${row.original.lastName}`,
      meta: { className: "@xl/table:w-2/5 @4xl/table:w-1/5" },
    }),
    columnHelper.accessor("username", {
      header: ({ column }) => (
        <DataTableColumnHeader column={column} title="Username" />
      ),
      cell: ({ getValue }) => <span className="font-medium">{getValue()}</span>,
      // No width below 4xl, so the username takes the room the hidden columns leave.
      meta: { className: "@4xl/table:w-1/6" },
    }),
    columnHelper.accessor("email", {
      header: ({ column }) => (
        <DataTableColumnHeader column={column} title="Email" />
      ),
      cell: ({ getValue }) =>
        getValue() ?? <span className="text-muted-foreground">-</span>,
      enableSorting: false,
    }),
    columnHelper.accessor("active", {
      header: ({ column }) => (
        <DataTableColumnHeader column={column} title="Status" />
      ),
      cell: ({ getValue }) =>
        getValue() ? (
          <StatusBadge tone="success">Active</StatusBadge>
        ) : (
          <StatusBadge tone="destructive">Inactive</StatusBadge>
        ),
      meta: { className: "w-32" },
    }),
    columnHelper.display({
      id: "actions",
      header: () => <span className="sr-only">Actions</span>,
      cell: ({ row }) => (
        <UserActions
          onEdit={() => actions.onEdit(row.original.id)}
          onResetPassword={() => actions.onResetPassword(row.original.id)}
          username={row.original.username}
        />
      ),
      meta: { className: "w-16" },
    }),
  ])

function UserActions({
  username,
  onEdit,
  onResetPassword,
}: { username: string } & Record<"onEdit" | "onResetPassword", () => void>) {
  return (
    <div className="flex justify-end">
      <DropdownMenu>
        <DropdownMenuTrigger
          render={
            <Button
              aria-label={`Actions for ${username}`}
              size="icon-sm"
              variant="ghost"
            />
          }
        >
          <EllipsisIcon />
        </DropdownMenuTrigger>
        <DropdownMenuContent align="end" className="w-auto">
          <DropdownMenuItem onClick={onEdit}>
            <PencilIcon />
            Edit
          </DropdownMenuItem>
          <DropdownMenuItem>
            <ShieldIcon />
            Roles
          </DropdownMenuItem>
          <DropdownMenuItem onClick={onResetPassword} variant="destructive">
            <KeyRoundIcon />
            Reset Password
          </DropdownMenuItem>
        </DropdownMenuContent>
      </DropdownMenu>
    </div>
  )
}
